'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var pdf = require( './../lib' );


// FIXTURES //

var data = require( './fixtures/python/data.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof pdf, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the function returns `NaN`', function test( t ) {
	var y = pdf( NaN, 0.0, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = pdf( 0.0, NaN, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = pdf( 0.0, 0.0, NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided `+infinity` for `x` and finite `mu` and `sigma`, the function returns `0`', function test( t ) {
	var y = pdf( PINF, 0.0, 1.0 );
	t.strictEqual( y, 0.0, 'returns expected value' );
	t.end();
});

tape( 'if provided `-infinity` for `x` and finite `mu` and `sigma`, the function returns `0`', function test( t ) {
	var y = pdf( NINF, 0.0, 1.0 );
	t.strictEqual( y, 0.0, 'returns expected value' );
	t.end();
});

tape( 'if provided `sigma <= 0`, the function returns `NaN`', function test( t ) {
	var y;

	y = pdf( 0.0, 0.0, -1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = pdf( 0.0, 0.0, 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = pdf( 0.0, 0.0, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'the function evaluates the pdf for `x` given `mu` and `sigma`', function test( t ) {
	var expected;
	var sigma;
	var mu;
	var x;
	var y;
	var i;

	expected = data.expected;
	x = data.x;
	mu = data.mu;
	sigma = data.sigma;

	for ( i = 0; i < x.length; i++ ) {
		y = pdf( x[i], mu[i], sigma[i] );
		if ( y === expected[i] ) {
			t.strictEqual( y, expected[i], 'x: '+x[i]+', mu: '+mu[i]+', σ: '+sigma[i]+', y: '+y+', expected: '+expected[i] );
		} else {
			t.ok( isAlmostSameValue( y, expected[i], 1 ), 'within tolerance. x: '+x[i]+'. mu: '+mu[i]+'. σ: '+sigma[i]+'. y: '+y+'. E: '+expected[i]+'.' );
		}
	}
	t.end();
});
